#include "GaplessAacTail.hpp"
#include <iostream>
using namespace udm;
static Bytes words(std::initializer_list<uint32_t> values){Bytes out;for(auto value:values)aac_tail::u32(out,value);return out;}
static Bytes join(std::initializer_list<Bytes> values){Bytes out;for(const auto& value:values)aac_tail::append(out,value);return out;}
static Bytes box(const char* type,const Bytes& body){return aac_tail::box(type,body);}
static Bytes track(bool source,bool edit=false,uint32_t packet=1024,bool shortSizes=false){
 auto entry=words({0,1,0,0,0x00010010,0,48000U<<16});auto table=join({box("stsd",join({words({0,1}),box("mp4a",entry)})),box("stts",source?words({0,0}):words({0,1,47,packet})),box("stsz",source?words({0,0,0}):words({0,shortSizes?0U:1U,47}))});
 auto media=box("mdia",join({box("mdhd",words({0,0,0,48000,source?0U:47U*packet,0})),box("hdlr",join({words({0,0}),Bytes{'s','o','u','n'},words({0,0,0})})),box("minf",box("stbl",table))}));
 return box("trak",join({box("tkhd",words({3,0,0,1,0,1003})),media,edit?box("edts",box("elst",words({0,1,1003,128,65536}))):Bytes{}}));
}
static Bytes metadata(const std::string& marker,bool duplicate=false,bool custom=false){
 const char encoder[4]={char(0xa9),'t','o','o'};auto tag=box(encoder,aac_tail::textData(marker));Bytes list=tag;if(duplicate)aac_tail::append(list,tag);
 if(custom){Bytes name(4);const std::string value="DISCSUBTITLE";name.insert(name.end(),value.begin(),value.end());aac_tail::append(list,box("----",join({box("name",name),aac_tail::textData("Owned disc title")})));}
 return box("udta",box("meta",join({words({0}),box("hdlr",join({words({0,0}),Bytes{'m','d','i','r'},Bytes(13)})),box("ilst",list)})));
}
static Bytes source(uint32_t time=0,bool edit=false){return join({box("ftyp",Bytes{'i','s','o','m'}),box("moov",track(true,edit)),box("moof",box("traf",join({box("tfhd",words({0,1})),box("tfdt",words({0,time}))}))),box("mdat",Bytes{1})});}
static Bytes output(bool edit=false,uint32_t duration=1024,bool shortSizes=false,bool duplicate=false,bool custom=false,const std::string& marker=gaplessAacTailReserve()){
 auto caption=box("trak",box("mdia",box("hdlr",join({words({0,0}),Bytes{'t','e','x','t'}}))));return join({box("ftyp",Bytes{'i','s','o','m'}),box("moov",join({track(false,edit,duration,shortSizes),caption,metadata(marker,duplicate,custom)})),box("mdat",Bytes(47,0x5a))});
}
int wmain(int argc,wchar_t** argv){if(argc!=2||fs::exists(argv[1]))return 2;const auto root=fs::absolute(argv[1]);fs::create_directories(root);Json checks=Json::array();std::string error;auto check=[&](bool ok,const char* name){checks.push_back({{"name",name},{"passed",ok}});if(!ok)throw std::runtime_error(name);};
 try{Cancel cancel;const auto input=root/L"source.mp4";writeBytes(input,source());const Json probe={{"streams",Json::array({{{"codec_type","audio"},{"codec_name","aac"},{"profile","LC"},{"sample_rate","48000"}}})}};
  auto plan=gaplessAacTailCandidate(input,probe,1,cancel);check(plan&&plan->samples==48000&&plan->rate==48000,"Zero-origin fragmented AAC LC admits an integral partial-tail plan");
  check(!gaplessAacTailCandidate(input,probe,1.024,cancel),"Already aligned samples need no reservation");check(!gaplessAacTailCandidate(input,probe,std::numeric_limits<double>::quiet_NaN(),cancel),"Nonfinite intervals cannot create a plan");auto changed=probe;changed["streams"][0]["profile"]="HE-AAC";check(!gaplessAacTailCandidate(input,changed,1,cancel),"Unqualified AAC profiles retain the existing path");writeBytes(input,source(1024));check(!gaplessAacTailCandidate(input,probe,1,cancel),"Nonzero encoded origins cannot imply a zero-origin tail");writeBytes(input,source(0,true));check(!gaplessAacTailCandidate(input,probe,1,cancel),"Initialization edits cannot silently change leading sample ownership");
  const auto target=root/L"output.mp4";auto original=output(false,1024,false,false,true);writeBytes(target,original);auto result=finalizeGaplessAacTail(target,*plan,cancel);auto actual=readText(target);check(result.applied&&result.padding==128,"Only the final partial AAC packet is declared as padding");check(actual.size()==original.size(),"Reserved metadata keeps the exact final file size");check(actual.substr(actual.size()-47)==std::string(47,char(0x5a)),"Encoded media bytes remain unchanged");check(actual.find("Owned disc title")!=std::string::npos&&actual.find("iTunSMPB")!=std::string::npos&&actual.find(gaplessAacTailReserve())==std::string::npos,"Custom metadata survives and no internal reservation leaks");
  Bytes bytes(actual.begin(),actual.end());aac_tail::Reader reader{bytes,cancel};size_t at=0;reader.box(at,bytes.size());auto movie=reader.box(at,bytes.size());auto children=reader.children(movie);check(children.size()==3&&children[0].type=="trak"&&children[1].type=="udta"&&children[2].type=="trak","Global padding metadata is parsed after AAC and before later captions");
  const auto rejects=[&](const Bytes& value,GaplessAacTailPlan request,const char* name){writeBytes(target,value);const auto before=fileHash(target);bool denied=false;try{finalizeGaplessAacTail(target,request,cancel);}catch(const std::exception&){denied=true;}check(denied&&fileHash(target)==before,name);};
  rejects(output(),{44100,44100},"Changed sample rate is rejected before any write");rejects(output(),{48000,46000},"Whole-packet trimming is not disguised as padding");rejects(output(true),*plan,"Nonzero leading edits are rejected without modifying the file");rejects(output(false,960),*plan,"Unsupported packet lengths cannot use the LC tail rule");rejects(output(false,1024,true),*plan,"Truncated variable sample-size tables cannot authorize a patch");rejects(output(false,1024,false,true),*plan,"Duplicate reservations are rejected without modification");rejects(output(false,1024,false,false,false,"Other encoding tool"),*plan,"Unrecognized metadata cannot be overwritten as a reservation");
  auto truncated=output();truncated.pop_back();rejects(truncated,*plan,"A truncated movie body is rejected before metadata writes");writeBytes(target,output());const auto before=fileHash(target);Cancel stopped;stopped.stop=true;bool cancelled=false;try{finalizeGaplessAacTail(target,*plan,stopped);}catch(const Cancelled&){cancelled=true;}check(cancelled&&fileHash(target)==before,"Parent cancellation preserves an unmodified staging file");
 }catch(const std::exception& e){error=e.what();}atomicText(root/L"results.json",Json{{"passed",error.empty()},{"checks",checks},{"error",error}}.dump(2),false);std::cout<<checks.size()<<" checks; "<<error<<"\n";return error.empty()?0:1;
}
